<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { actualizarTipoTrabajo, crearTipoTrabajo, listarTiposTrabajo } from '../services/tiposTrabajo'
import type { TipoTrabajo } from '../interfaces/tiposTrabajo.interface'
const rows=ref<TipoTrabajo[]>([]),editing=ref<TipoTrabajo|null>(null),detail=ref<TipoTrabajo|null>(null),modal=ref(false),criterio=ref(''),estado=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const form=reactive({tipo:'',descripcion:'',duracion:'',proceso:'',se_informa:'',movimiento_genera:'',activo:true})
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const r=await listarTiposTrabajo(criterio.value,estado.value,p);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=msg(e)}finally{loading.value=false}}
function open(x?:TipoTrabajo){editing.value=x||null;Object.assign(form,{tipo:x?.tipo||'',descripcion:x?.descripcion||'',duracion:x?.duracion||'',proceso:x?.proceso||'',se_informa:x?.se_informa||'',movimiento_genera:x?.movimiento_genera||'',activo:x?.activo??true});modal.value=true}
function editDetail(){const x=detail.value;if(!x)return;detail.value=null;open(x)}
async function submit(){if(Object.entries(form).some(([k,v])=>k!=='activo'&&!String(v).trim())){error.value='Complete todos los datos del tipo de trabajo.';return}saving.value=true;error.value='';try{editing.value?await actualizarTipoTrabajo(editing.value.id,form):await crearTipoTrabajo(form);success.value=editing.value?'Tipo de trabajo actualizado.':'Tipo de trabajo registrado.';modal.value=false;await load(page.value)}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Tipos de trabajo</nav><header class="hero"><div class="mark">TT</div><div><small>EVAN · CONFIGURACIÓN COMERCIAL</small><h1>Tipos de trabajo</h1><p>Labores disponibles para las acciones de los flujos de atención.</p></div><strong>{{total}} tipos</strong><button @click="open()">+ Registrar tipo</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Tipo, descripción o proceso" @keyup.enter="load(1)"></label><label>Estado<select v-model="estado"><option value="">Todos</option><option value="1">Activos</option><option value="0">Inactivos</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando tipos de trabajo…</div><div v-else-if="!rows.length" class="empty">No se encontraron tipos de trabajo.</div><section v-else class="table"><header><span>Tipo de trabajo</span><span>Duración</span><span>Proceso</span><span>Estado</span><span>Acciones</span></header><article v-for="x in rows" :key="x.id"><div><b>{{x.tipo}}</b><small>{{x.descripcion}}</small></div><span>{{x.duracion}}</span><span>{{x.proceso}}</span><em :class="{off:!x.activo}">{{x.activo?'Activo':'Inactivo'}}</em><div class="actions"><button @click="detail=x">Ver</button><button @click="open(x)">Editar</button></div></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div><small>DETALLE DEL TIPO DE TRABAJO</small><h2>{{detail.tipo}}</h2><p>{{detail.descripcion}}</p></div><button @click="detail=null">×</button></header><dl><div><dt>Duración</dt><dd>{{detail.duracion}}</dd></div><div><dt>Proceso</dt><dd>{{detail.proceso}}</dd></div><div><dt>Se informa</dt><dd>{{detail.se_informa}}</dd></div><div><dt>Movimiento que genera</dt><dd>{{detail.movimiento_genera}}</dd></div><div><dt>Usos en flujos</dt><dd>{{detail.usos||0}}</dd></div></dl><footer><button class="clear" @click="detail=null">Cerrar</button><button @click="editDetail">Modificar</button></footer></section></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="submit"><header><div><small>TIPO DE TRABAJO</small><h2>{{editing?'Modificar registro':'Registrar nuevo tipo'}}</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Tipo de trabajo *<input v-model.trim="form.tipo" maxlength="50" required></label><label>Duración *<input v-model.trim="form.duracion" maxlength="100" required></label></div><label>Descripción *<textarea v-model.trim="form.descripcion" maxlength="255" rows="3" required></textarea></label><div class="grid"><label>Proceso *<input v-model.trim="form.proceso" maxlength="100" required></label><label>Se informa *<input v-model.trim="form.se_informa" maxlength="100" required></label></div><label>Movimiento que genera *<input v-model.trim="form.movimiento_genera" maxlength="100" required></label><label class="check"><input v-model="form.activo" type="checkbox"> Registro activo</label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#267bbd;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.56rem}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.58rem}.table{margin-top:12px;background:#fff}.table>header,.table article{padding:11px 15px;display:grid;grid-template-columns:2.5fr 1fr 1.3fr .7fr 1fr;align-items:center;gap:8px;border-bottom:1px solid #e9edef;font-size:.53rem}.table>header{color:#849096;background:#f6f8f9;font-size:.48rem;font-weight:700}.table article b,.table article small{display:block}.table article small{margin-top:3px;color:#7d898f;font-size:.48rem}.table em{justify-self:start;padding:4px 7px;border-radius:9px;color:#26785b;background:#e9f8f1;font-size:.46rem;font-style:normal}.table em.off{color:#92545a;background:#faeded}.actions button{border:0;color:var(--a);background:none;font-size:.49rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,720px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin:11px 0;font-size:.55rem}.grid,.modal dl{display:grid;grid-template-columns:1fr 1fr;gap:8px}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}.modal dl div{padding:10px;background:#f5f8f9}.modal dt{color:#849096;font-size:.48rem}.modal dd{margin:3px 0;font-size:.55rem;font-weight:700}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}@media(max-width:800px){.table{overflow:auto}.table>header,.table article{min-width:700px}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:500px){.grid,.modal dl{grid-template-columns:1fr}}
</style>
